import { lazy } from 'react';
import { ArrowLeftRight as IcArrowLeftRight, Factory as IcFactory, HardHat as IcHardHat, RefreshCw as IcRefreshCw, Settings2 as IcSettings2 } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Attendance Configuration — hub page for the Attendance menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 5 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'AttendanceConfig'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const Shifts = lazy(() => import('../../hr/pages/Shifts'));
const WorkCentres = lazy(() => import('./WorkCentres'));
const ContractLabour = lazy(() => import('./ContractLabour'));
const PayrollSync = lazy(() => import('./PayrollSync'));
const AttendanceSettings = lazy(() => import('./AttendanceSettings'));

export const TABS = [
  { id: 'rotations', label: 'Shift Rotations', icon: IcRefreshCw, page: 'Shifts', Component: Shifts },
  { id: 'workcentres', label: 'Work Centres', icon: IcFactory, page: 'WorkCentres', Component: WorkCentres },
  { id: 'contract', label: 'Contract Labour', icon: IcHardHat, page: 'ContractLabour', Component: ContractLabour },
  { id: 'sync', label: 'Payroll Sync', icon: IcArrowLeftRight, page: 'PayrollSync', Component: PayrollSync },
  { id: 'settings', label: 'Settings', icon: IcSettings2, page: 'AttendanceSettings', Component: AttendanceSettings },
];

export default function AttendanceConfig({ setPage }) {
  return (
    <TabHub
      icon={IcSettings2}
      eyebrow="Attendance"
      title="Attendance Configuration"
      subtitle="Shift rotations, work centres, contract labour, payroll sync and module settings"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
